// Some portions generated by Claude
import { LARGE_GRAPH_NODES } from "./explorer-config.ts";
import type { Graph } from "./graph-types.ts";

/**
 * When the graph has changed enough since its last full layout to look better laid out again, and how long that
 * layout would take. Expanding, hiding, showing values and finding links place or take away only the nodes and links
 * they change; the rest of the drawing keeps the shape the last full layout gave it.
 */

export type LayoutMode = "network" | "hierarchy" | "square";

/** The drawn nodes and links the last full layout placed, and the layout it was. */
export type LaidOutGraph = { nodeIds: ReadonlySet<string>; linkIds: ReadonlySet<string>; mode: LayoutMode };

/** How long a full layout of a drawn graph of this size took, from asking for it to its positions. */
export type LayoutTiming = { nodes: number; links: number; durationMs: number };

/** Nodes and links drawn now that the last layout did not place, or that it placed and are gone. */
export type RelayoutSuggestion = { nodes: number; links: number; mode: LayoutMode };

/** Arrows are routed by the layout below this many drawn nodes (the SVG canvas draws them; see `LARGE_GRAPH_NODES`). */
export const ROUTED_LAYOUT_NODES = LARGE_GRAPH_NODES;

/**
 * Above this many drawn nodes the multilevel engine lays the graph out, much faster than the organic engine below it.
 * The layout engine's `ORGANIC_LIMIT`, repeated so that the page does not load the engine (it runs in a worker).
 */
export const MULTILEVEL_LAYOUT_NODES = 1500;

/** A layout is suggested once at least this many nodes and links changed, */
const MIN_CHANGES = 4;
/** and at least this share of the nodes and links drawn then or now. */
const CHANGE_SHARE = 0.1;

type DrawnGraph = Pick<Graph, "nodes" | "edges">;

export function laidOutGraph(graph: DrawnGraph, mode: LayoutMode = "network"): LaidOutGraph {
  return {
    nodeIds: new Set(graph.nodes.map((node) => node.id)),
    linkIds: new Set(graph.edges.map((edge) => edge.id)),
    mode,
  };
}

function changed(before: ReadonlySet<string>, now: readonly { id: string }[]) {
  let kept = 0;
  for (const item of now) if (before.has(item.id)) kept++;
  return now.length - kept + (before.size - kept);
}

/** What changed since the last full layout, when that is enough to lay the graph out again; otherwise null. */
export function relayoutSuggestion(laidOut: LaidOutGraph, graph: DrawnGraph): RelayoutSuggestion | null {
  const nodes = changed(laidOut.nodeIds, graph.nodes);
  const links = changed(laidOut.linkIds, graph.edges);
  const size = Math.max(laidOut.nodeIds.size + laidOut.linkIds.size, graph.nodes.length + graph.edges.length);
  const enough = nodes + links >= Math.max(MIN_CHANGES, Math.ceil(size * CHANGE_SHARE));
  return enough ? { nodes, links, mode: laidOut.mode } : null;
}

/** "6 nodes and 1 link were added or taken away". */
export function describeRelayoutChanges({ nodes, links }: RelayoutSuggestion) {
  const counted = (count: number, noun: string) => `${count} ${noun}${count === 1 ? "" : "s"}`;
  const parts = [nodes ? counted(nodes, "node") : "", links ? counted(links, "link") : ""].filter(Boolean);
  return `${parts.join(" and ")} ${nodes + links === 1 ? "was" : "were"} added or taken away`;
}

/** What every layout costs on the page, whatever its size: handing the graph to the worker and the positions back. */
const LAYOUT_START_MS = 50;

/**
 * The relative cost of a full layout, in milliseconds of the machine that measured it, from timings of the
 * representative graph (`representative-graph.mjs`, about three links per node, and a third of its links) at 11 to
 * 50,000 nodes. Routing the arrows dominates below `ROUTED_LAYOUT_NODES` and grows with nodes and links; the organic
 * engine grows with the square of the nodes; the multilevel engine about linearly. Each fits its timings within a
 * factor of about two.
 */
function layoutCost(nodes: number, links: number) {
  if (nodes > MULTILEVEL_LAYOUT_NODES) return LAYOUT_START_MS + 0.000537 * (nodes + links) ** 1.19;
  if (nodes >= ROUTED_LAYOUT_NODES) return LAYOUT_START_MS + 0.00176 * nodes ** 1.98;
  return LAYOUT_START_MS + 0.0501 * (nodes + links) ** 1.44;
}

/** The last layout's time, scaled by how much more (or less) work this graph is: the machine stays as fast. */
export function estimateLayoutMs(previous: LayoutTiming, nodes: number, links: number) {
  return previous.durationMs * (layoutCost(nodes, links) / layoutCost(previous.nodes, previous.links));
}

/** "under a second", "about 3 s", "about 25 s", "about 2 min": an estimate is no more precise than that. */
export function describeLayoutDuration(ms: number) {
  if (ms < 1000) return "under a second";
  const seconds = ms < 10_000 ? Math.round(ms / 1000) : 5 * Math.round(ms / 5000);
  return seconds < 60 ? `about ${seconds} s` : `about ${Math.max(1, Math.round(ms / 60_000))} min`;
}

const timingKey = (mode: LayoutMode) => `graph-field-layout-timing-${mode}-v1`;

/** The time this browser last took for a full layout of this kind; it differs from one machine to another. */
export function readLayoutTiming(
  storage: Pick<Storage, "getItem"> | undefined,
  mode: LayoutMode,
): LayoutTiming | undefined {
  try {
    const value = JSON.parse(storage?.getItem(timingKey(mode)) ?? "null");
    const { nodes, links, durationMs } = value ?? {};
    const counts = [nodes, links, durationMs];
    return counts.every((count) => typeof count === "number" && Number.isFinite(count) && count >= 0) && nodes > 0
      ? { nodes, links, durationMs }
      : undefined;
  } catch {
    return undefined;
  }
}

export function writeLayoutTiming(
  storage: Pick<Storage, "setItem"> | undefined,
  mode: LayoutMode,
  timing: LayoutTiming,
) {
  try {
    storage?.setItem(timingKey(mode), JSON.stringify(timing));
  } catch {
    // Without storage the estimate starts again from the next layout on this page.
  }
}
